21	func mustAccount(t *testing.T, w *Wallet, id string, bal int64) {
22		t.Helper()
23		if _, err := w.CreateAccount(id, bal); err != nil {
24			t.Fatalf("create account %s: %v", id, err)
25		}
26	}
