34	func TestCreateAccountAndBalance(t *testing.T) {
35		w, _ := newTestWallet()
36	
37		mustAccount(t, w, "payer", 100)
38		got, err := w.Balance("payer")
39		if err != nil {
40			t.Fatal(err)
41		}
42		if got.Available != 100 || got.Reserved != 0 {
43			t.Fatalf("balance = %+v, want {100 0}", got)
44		}
45	
46		if _, err := w.CreateAccount("payer", 1); !errors.Is(err, ErrAccountExists) {
47			t.Fatalf("dup account err = %v, want ErrAccountExists", err)
48		}
49		if _, err := w.CreateAccount("bad", -1); !errors.Is(err, ErrInvalidAmount) {
50			t.Fatalf("negative balance err = %v, want ErrInvalidAmount", err)
51		}
52		if _, err := w.Account("missing"); !errors.Is(err, ErrAccountNotFound) {
53			t.Fatalf("missing account err = %v, want ErrAccountNotFound", err)
54		}
55		// 失败的创建不得改变已有记录。
56		got, _ = w.Balance("payer")
57		if got.Available != 100 {
58			t.Fatalf("balance changed after failed creates: %+v", got)
59		}
60	}
