62	func TestSessions(t *testing.T) {
63		w, c := newTestWallet()
64		mustAccount(t, w, "u1", 0)
65	
66		exp := c.t.Add(time.Minute)
67		sess, err := w.CreateSession("s1", "u1", "dev1", exp)
68		if err != nil {
69			t.Fatal(err)
70		}
71		if sess.State != SessionActive || sess.ExpiresAt != exp {
72			t.Fatalf("session view = %+v", sess)
73		}
74		if _, err := w.CreateSession("s1", "u1", "dev1", exp); !errors.Is(err, ErrSessionExists) {
75			t.Fatalf("dup session err = %v", err)
76		}
77		if _, err := w.CreateSession("sx", "ghost", "d", exp); !errors.Is(err, ErrAccountNotFound) {
78			t.Fatalf("session for missing account err = %v", err)
79		}
80	
81		// 到期时刻本身即视为过期。
82		c.t = exp
83		if err := w.RevokeSession("s1"); err != nil {
84			t.Fatal(err)
85		}
86		view, _ := w.Session("s1")
87		if view.State != SessionRevoked {
88			t.Fatalf("state = %v, want revoked", view.State)
89		}
90		if err := w.RevokeSession("ghost"); !errors.Is(err, ErrSessionNotFound) {
91			t.Fatalf("revoke missing err = %v", err)
92		}
93		// 重复吊销幂等。
94		if err := w.RevokeSession("s1"); err != nil {
95			t.Fatalf("repeat revoke: %v", err)
96		}
97	}
