99	// validPolicy 构造一条在整个测试时间窗内有效的策略。
100	func validPolicy(c *clock) PolicySpec {
101		return PolicySpec{
102			ID:                "p1",
103			PayerAccountID:    "payer",
104			AllowedAccountIDs: []string{"u1", "u2"},
105			Operation:         "charge",
106			Payee:             "shop",
107			StartsAt:          c.t.Add(-time.Hour),
108			EndsAt:            c.t.Add(time.Hour),
109			MaxPerRequest:     30,
110			MaxTotal:          50,
111		}
112	}
113	
114	func TestSavePolicyValidation(t *testing.T) {
115		w, c := newTestWallet()
116		mustAccount(t, w, "payer", 100)
117		mustAccount(t, w, "u1", 0)
118		mustAccount(t, w, "u2", 0)
119	
120		good := validPolicy(c)
121		if err := w.SavePolicy(good); err != nil {
122			t.Fatal(err)
123		}
124		if err := w.SavePolicy(good); !errors.Is(err, ErrPolicyExists) {
125			t.Fatalf("dup policy err = %v", err)
126		}
127	
128		bad := good
129		bad.ID = "p-neg"
130		bad.MaxPerRequest = 0
131		if err := w.SavePolicy(bad); !errors.Is(err, ErrPolicyInvalid) {
132			t.Fatalf("non-positive per-request err = %v", err)
133		}
134		bad.ID, bad.MaxPerRequest, bad.MaxTotal = "p-neg2", 10, -1
135		if err := w.SavePolicy(bad); !errors.Is(err, ErrPolicyInvalid) {
136			t.Fatalf("negative total err = %v", err)
137		}
138		bad.ID, bad.MaxTotal, bad.EndsAt = "p-time", 50, bad.StartsAt
139		if err := w.SavePolicy(bad); !errors.Is(err, ErrPolicyInvalid) {
140			t.Fatalf("start==end err = %v", err)
141		}
142		bad.ID, bad.EndsAt, bad.PayerAccountID = "p-payer", c.t.Add(time.Hour), "ghost"
143		if err := w.SavePolicy(bad); !errors.Is(err, ErrPolicyInvalid) {
144			t.Fatalf("missing payer err = %v", err)
145		}
146		bad.ID, bad.PayerAccountID, bad.AllowedAccountIDs = "p-allowed", "payer", []string{"ghost"}
147		if err := w.SavePolicy(bad); !errors.Is(err, ErrPolicyInvalid) {
148			t.Fatalf("missing allowed account err = %v", err)
149		}
150	}
