152	func setupApply(t *testing.T) (*Wallet, *clock) {
153		t.Helper()
154		w, c := newTestWallet()
155		mustAccount(t, w, "payer", 100)
156		mustAccount(t, w, "u1", 0)
157		mustAccount(t, w, "u2", 0)
158		if _, err := w.CreateSession("s1", "u1", "dev1", c.t.Add(time.Minute)); err != nil {
159			t.Fatal(err)
160		}
161		if _, err := w.CreateSession("s2", "u2", "dev2", c.t.Add(time.Minute)); err != nil {
162			t.Fatal(err)
