9	
10	// 本文件为大额代付批准功能补充回归保障：每条策略有自己的累计额度，但出资
11	// 余额属于账户。两个使用账户通过两条不同策略提交的待审批请求，同时批准时
12	// 竞争的是同一个出资账户的可用余额——两条策略各自的累计额度都充足，也不
13	// 能让两笔合计超过出资余额的批准都成功；同样不能把不同策略的费用合并成
14	// 同一条策略的额度占用而误报额度超限。
15	//
16	// 固定场景（见 setupSharedPayerApproveContest）：
17	//   - 出资账户 payer 初始可用余额由用例给定（70 或恰为 90）、预留 0；
18	//     使用账户 u1/u2 余额为 0，分别持有绑定自有设备的有效会话 s1/d1、s2/d2；
19	//   - 策略 p-fee50 允许 u1、策略 p-fee40 允许 u2，出资账户同为 payer，
20	//     操作与收款方相同：单次上限各 60、累计上限各 100、审批门槛各 10、
21	//     审批等待各 1 小时，都关闭预留超时；
22	//   - u1 经 p-fee50 提交预估费用 50 的申请 r-50，u2 经 p-fee40 提交预估
23	//     费用 40 的申请 r-40；两笔都严格超过门槛且各自策略额度充足，都进入
24	//     待审批：payer 余额不变，两条策略的预留与已花费均为 0，账本只有两条
25	//     零金额待审批留痕。
26	const (
27		sharePayerPolicy50     = "p-fee50"
28		sharePayerPolicy40     = "p-fee40"
29		sharePayerRequest50    = "r-50"
30		sharePayerRequest40    = "r-40"
31		sharePayerFee50  int64 = 50
32		sharePayerFee40  int64 = 40
33		sharePayerPerReq int64 = 60
34		sharePayerMax    int64 = 100
35		sharePayerThresh int64 = 10
36	)
37	
38	// payerContestSide 描述竞争中一笔请求的定位信息（账户、策略、请求编号、费用）。
39	type payerContestSide struct {
40		account   string
41		policyID  string
42		requestID string
43		fee       int64
44	}
45	
46	var (
47		sharePayerSide50 = payerContestSide{"u1", sharePayerPolicy50, sharePayerRequest50, sharePayerFee50}
48		sharePayerSide40 = payerContestSide{"u2", sharePayerPolicy40, sharePayerRequest40, sharePayerFee40}
49	)
50	
51	// setupSharedPayerApproveContest 构造上述固定场景，提交两笔申请并断言起点：
52	// 两笔均待审批、提交与等待截止时间各自记录；payer 可用 payerInit / 预留 0；
53	// 两条策略的预留总额与已花费总额都为 0；账本恰有两条待审批留痕，出资账户
54	// 名下没有任何资金记录。返回提交时刻（两笔相同）与等待截止时刻（两笔相同）。
55	func setupSharedPayerApproveContest(t *testing.T, payerInit int64) (*Wallet, *clock, time.Time, time.Time) {
56		t.Helper()
57		w, c := newTestWallet()
58		mustAccount(t, w, "payer", payerInit)
59		mustAccount(t, w, "u1", 0)
60		mustAccount(t, w, "u2", 0)
61		if _, err := w.CreateSession("s1", "u1", "d1", c.t.Add(24*time.Hour)); err != nil {
62			t.Fatal(err)
63		}
64		if _, err := w.CreateSession("s2", "u2", "d2", c.t.Add(24*time.Hour)); err != nil {
65			t.Fatal(err)
66		}
67		if _, err := w.CreateSession("sa", "payer", "d-approve", c.t.Add(24*time.Hour)); err != nil {
68			t.Fatal(err)
69		}
70		// 两条策略共用出资账户，其余配置相同，仅编号与授权账户不同。
71		for _, p := range []PolicySpec{
72			{ID: sharePayerPolicy50, AllowedAccountIDs: []string{"u1"}},
73			{ID: sharePayerPolicy40, AllowedAccountIDs: []string{"u2"}},
74		} {
75			p.PayerAccountID = "payer"
76			p.Operation = "charge"
77			p.Payee = "shop"
78			p.StartsAt = c.t.Add(-time.Hour)
79			p.EndsAt = c.t.Add(24 * time.Hour)
80			p.MaxPerRequest = sharePayerPerReq
81			p.MaxTotal = sharePayerMax
82			p.ApprovalThreshold = sharePayerThresh
83			p.ApprovalWait = time.Hour
84			// MaxReserveDuration 留空（零）：关闭预留超时。
85			if err := w.SavePolicy(p); err != nil {
86				t.Fatal(err)
87			}
88		}
89	
90		apply := func(side payerContestSide, session, device string) RequestView {
91			req, err := w.Apply(RequestInput{
92				PolicyID:     side.policyID,
93				RequestID:    side.requestID,
94				AccountID:    side.account,
95				SessionID:    session,
96				DeviceID:     device,
97				Operation:    "charge",
98				Payee:        "shop",
99				EstimatedFee: side.fee,
100			})
101			if err != nil {
102				t.Fatalf("apply for %s: %v", side.account, err)
103			}
104			return req
105		}
106		r50 := apply(sharePayerSide50, "s1", "d1")
107		r40 := apply(sharePayerSide40, "s2", "d2")
108		if r50.State != RequestPendingApproval || r40.State != RequestPendingApproval {
109			t.Fatalf("both requests must be pending approval, got %v and %v", r50.State, r40.State)
110		}
111		if !r50.CreatedAt.Equal(c.t) || !r40.CreatedAt.Equal(c.t) {
112			t.Fatalf("created at = %v / %v, want %v", r50.CreatedAt, r40.CreatedAt, c.t)
113		}
114		wantDeadline := c.t.Add(time.Hour)
115		if !r50.WaitDeadline.Equal(wantDeadline) || !r40.WaitDeadline.Equal(wantDeadline) {
116			t.Fatalf("wait deadlines = %v / %v, want %v", r50.WaitDeadline, r40.WaitDeadline, wantDeadline)
117		}
118		// 待审批不允许有任何预留或决定信息。
119		for _, r := range []RequestView{r50, r40} {
120			if !r.ReservedAt.IsZero() || !r.DecidedAt.IsZero() || r.ApproverAccountID != "" || r.RejectReason != "" {
121				t.Fatalf("pending request must carry no reservation or decision: %+v", r)
122			}
123		}
124	
125		// 待审批不冻结余额、不占用任何策略的累计额度：出资账户余额不变，
126		// 两条策略的预留总额与已花费总额都为零。
127		if bal, _ := w.Balance("payer"); bal != (Balances{Available: payerInit, Reserved: 0}) {
128			t.Fatalf("payer balance after two pending applies = %+v, want {%d 0}", bal, payerInit)
129		}
130		for _, pid := range []string{sharePayerPolicy50, sharePayerPolicy40} {
131			if pv, _ := w.Policy(pid); pv.ReservedTotal != 0 || pv.SpentTotal != 0 {
132				t.Fatalf("policy %s totals after two pending applies = reserved %d spent %d, want 0/0",
133					pid, pv.ReservedTotal, pv.SpentTotal)
134			}
135		}
136		// 账本只有两条零金额待审批留痕，出资账户名下没有任何资金记录。
137		all := w.Ledger()
138		if len(all) != 2 {
139			t.Fatalf("ledger after applies = %d entries, want 2 pending entries: %+v", len(all), all)
140		}
141		for _, e := range all {
142			if e.Kind != LedgerPendingApproval || e.Amount != 0 {
143				t.Fatalf("entry = %+v, want zero-amount pending-approval entry", e)
144			}
145		}
146		if len(w.AccountLedger("payer")) != 0 {
147			t.Fatalf("pending approvals must not create payer money entries: %+v", w.AccountLedger("payer"))
148		}
149		return w, c, c.t, wantDeadline
150	}
151	
152	// checkSharedPayerOutcome 校验“两笔待审批同时批准、恰有一笔成功”后的统一
153	// 结果，不预设胜出者：
154	//   - winner 一侧的请求已预留其费用：带出资账户的批准决定，预留时刻即批准
155	//     时刻；提交时间与等待截止时间保持申请时原值；
156	//   - loser 一侧的请求仍待审批：没有预留计时或任何审批决定字段，提交时间
157	//     与等待截止时间保持原值（失败批准不推进期限、不开始预留计时）；
158	//   - payer 可用 payerInit-winner.fee / 预留 winner.fee；只有 winner 所属
159	//     策略的预留总额增加对应费用，loser 所属策略保持零预留，两条策略的
160	//     已花费总额都不增加；
161	//   - 原有两条待审批留痕保留；只为胜出请求新增一条 payer 的全额预留记录与
162	//     一条使用账户的零金额批准记录；失败批准不新增资金记录或审批决定。
163	func checkSharedPayerOutcome(t *testing.T, w *Wallet, payerInit int64,
164		winner, loser payerContestSide, createdAt, waitDeadline, approveAt time.Time) {
165		t.Helper()
166		if winner == loser {
167			t.Fatalf("winner and loser must be different sides, got %+v", winner)
168		}
169	
170		winReq, err := w.Request(winner.account, winner.requestID)
171		if err != nil {
172			t.Fatal(err)
173		}
174		if winReq.State != RequestReserved {
175			t.Fatalf("winner %s state = %v, want reserved", winner.requestID, winReq.State)
176		}
177		if winReq.EstimatedFee != winner.fee {
178			t.Fatalf("winner estimated fee = %d, want %d", winReq.EstimatedFee, winner.fee)
179		}
180		if winReq.PolicyID != winner.policyID {
181			t.Fatalf("winner policy = %q, want %q", winReq.PolicyID, winner.policyID)
182		}
183		if winReq.ApproverAccountID != "payer" {
184			t.Fatalf("winner approver = %q, want payer", winReq.ApproverAccountID)
185		}
186		if !winReq.DecidedAt.Equal(approveAt) || !winReq.ReservedAt.Equal(approveAt) {
187			t.Fatalf("winner decided/reserved at %v/%v, want approve time %v",
188				winReq.DecidedAt, winReq.ReservedAt, approveAt)
189		}
190		// 批准成功保留原提交时刻与等待截止时刻。
191		if !winReq.CreatedAt.Equal(createdAt) || !winReq.WaitDeadline.Equal(waitDeadline) {
192			t.Fatalf("winner timing changed: created %v want %v, deadline %v want %v",
193				winReq.CreatedAt, createdAt, winReq.WaitDeadline, waitDeadline)
194		}
195		if winReq.RejectReason != "" {
196			t.Fatalf("reserved winner must not carry reject reason: %q", winReq.RejectReason)
197		}
198	
199		loseReq, err := w.Request(loser.account, loser.requestID)
200		if err != nil {
201			t.Fatal(err)
202		}
203		if loseReq.State != RequestPendingApproval {
204			t.Fatalf("loser %s state = %v, want still pending approval (must not become rejected)",
205				loser.requestID, loseReq.State)
206		}
207		// 失败批准不留任何决定、不开始预留计时。
208		if !loseReq.DecidedAt.IsZero() || loseReq.ApproverAccountID != "" || loseReq.RejectReason != "" {
209			t.Fatalf("loser decision fields changed on failed approve: %+v", loseReq)
210		}
211		if !loseReq.ReservedAt.IsZero() || loseReq.ReserveDuration != 0 || !loseReq.ReserveDeadline.IsZero() {
212			t.Fatalf("loser reserve timing started on failed approve: %+v", loseReq)
213		}
214		// 提交时间与等待截止时间保持原值。
215		if !loseReq.CreatedAt.Equal(createdAt) || !loseReq.WaitDeadline.Equal(waitDeadline) {
216			t.Fatalf("loser timing changed: created %v want %v, deadline %v want %v",
217				loseReq.CreatedAt, createdAt, loseReq.WaitDeadline, waitDeadline)
218		}
219		if loseReq.EstimatedFee != loser.fee {
220			t.Fatalf("loser estimated fee = %d, want %d", loseReq.EstimatedFee, loser.fee)
221		}
222	
223		// 出资余额属于账户：胜出预留从 payer 可用余额划出，与策略条数无关。
224		wantBal := Balances{Available: payerInit - winner.fee, Reserved: winner.fee}
225		if bal, _ := w.Balance("payer"); bal != wantBal {
226			t.Fatalf("payer balance = %+v, want %+v", bal, wantBal)
227		}
228		// 只有胜出请求所属策略增加对应预留；另一条策略保持零预留；
229		// 两条策略的已花费总额都不增加。
230		if pv, _ := w.Policy(winner.policyID); pv.ReservedTotal != winner.fee || pv.SpentTotal != 0 {
231			t.Fatalf("winner policy %s totals = reserved %d spent %d, want %d/0",
232				winner.policyID, pv.ReservedTotal, pv.SpentTotal, winner.fee)
233		}
234		if pv, _ := w.Policy(loser.policyID); pv.ReservedTotal != 0 || pv.SpentTotal != 0 {
235			t.Fatalf("loser policy %s totals = reserved %d spent %d, want 0/0",
236				loser.policyID, pv.ReservedTotal, pv.SpentTotal)
237		}
238	
239		// 账本：两条原待审批留痕 + 胜出请求的一条全额预留 + 一条零金额批准，
240		// 共 4 条；失败批准不新增任何记录。
241		all := w.Ledger()
242		if len(all) != 4 {
243			t.Fatalf("ledger entries = %d, want 4 (2 pending + reserve + approval): %+v", len(all), all)
244		}
245		if got := countKind(all, LedgerPendingApproval); got != 2 {
246			t.Fatalf("pending entries = %d, want original 2 preserved", got)
247		}
248		if got := countKind(all, LedgerReserve); got != 1 {
249			t.Fatalf("reserve entries = %d, want exactly 1 for the winner", got)
250		}
251		if got := countKind(all, LedgerApproval); got != 1 {
252			t.Fatalf("approval entries = %d, want exactly 1 for the winner", got)
253		}
254		for _, kind := range []LedgerKind{LedgerRejection, LedgerRefund, LedgerSettle, LedgerExpiration, LedgerCancellation} {
255			if got := countKind(all, kind); got != 0 {
256				t.Fatalf("ledger kind %v entries = %d, want none after contested approvals", kind, got)
257			}
258		}
259		res, ok := ledgerEntryFor(all, LedgerReserve, winner.requestID)
260		if !ok {
261			t.Fatal("missing reserve entry for winner")
262		}
263		if res.AccountID != "payer" || res.Amount != winner.fee || !res.At.Equal(approveAt) {
264			t.Fatalf("winner reserve entry = %+v, want payer %d at approve time", res, winner.fee)
265		}
266		app, ok := ledgerEntryFor(all, LedgerApproval, winner.requestID)
267		if !ok {
268			t.Fatal("missing zero-amount approval entry for winner")
269		}
270		if app.AccountID != winner.account || app.Amount != 0 || !app.At.Equal(approveAt) {
271			t.Fatalf("winner approval entry = %+v, want zero-amount entry for %s at approve time", app, winner.account)
272		}
273		// 两条待审批留痕仍分别归属 u1、u2，失败批准没有把失败方转成拒绝留痕。
274		pendingAccounts := map[string]int{}
275		for _, e := range all {
276			if e.Kind == LedgerPendingApproval {
277				pendingAccounts[e.AccountID]++
278			}
279		}
280		if pendingAccounts["u1"] != 1 || pendingAccounts["u2"] != 1 {
281			t.Fatalf("pending traces = %+v, want one each for u1 and u2", pendingAccounts)
282		}
283	}
284	
285	// approveSharedPayer 用出资账户的有效审批会话批准指定一侧的竞争请求。
286	func approveSharedPayer(w *Wallet, side payerContestSide) (RequestView, error) {
287		return w.Approve(side.account, side.requestID, "sa", "d-approve")
288	}
289	
290	// TestSharedPayerSequentialContestedApprovals 顺序复现跨策略争用：出资账户
291	// 可用 70，两条策略各自的累计额度都充足（50 ≤ 100、40 ≤ 100），但两笔费用
292	// 合计 90 超过出资余额。同一时刻连续批准两笔待审批请求，只能有一笔成功
293	// 预留，另一笔返回 ErrInsufficientBalance 并继续待审批——不能误报额度超限
294	// （每条策略自己的额度都够），也不能转成拒绝终态。两种先后顺序都覆盖：
295	// 50 先获批时余额为 20 可用 / 50 预留，40 先获批时为 30 可用 / 40 预留。
296	func TestSharedPayerSequentialContestedApprovals(t *testing.T) {
297		const payerInit int64 = 70
298		for _, order := range []struct {
299			name   string
300			first  payerContestSide
301			second payerContestSide
302		}{
303			{"fee50-first", sharePayerSide50, sharePayerSide40},
304			{"fee40-first", sharePayerSide40, sharePayerSide50},
305		} {
306			t.Run(order.name, func(t *testing.T) {
307				w, c, createdAt, waitDeadline := setupSharedPayerApproveContest(t, payerInit)
308				approveAt := c.t.Add(10 * time.Second)
309				c.t = approveAt
310	
311				first, err := approveSharedPayer(w, order.first)
312				if err != nil {
313					t.Fatalf("first approve of %s: %v", order.first.requestID, err)
314				}
315				if first.State != RequestReserved {
316					t.Fatalf("first approve state = %v, want reserved", first.State)
317				}
318				// 第二笔：两条策略各自的累计额度都充足，但第一笔预留后 payer
319				// 可用余额已不足第二笔费用，必须按余额不足失败而非额度超限。
320				if _, err := approveSharedPayer(w, order.second); !errors.Is(err, ErrInsufficientBalance) {
321					t.Fatalf("second approve of %s err = %v, want ErrInsufficientBalance", order.second.requestID, err)
322				} else if errors.Is(err, ErrQuotaExceeded) {
323					t.Fatalf("second approve must fail on payer balance, not policy quota: %v", err)
324				}
325				checkSharedPayerOutcome(t, w, payerInit, order.first, order.second, createdAt, waitDeadline, approveAt)
326	
327				// 期限内立即再次批准失败方：余额仍被胜出预留占用，依旧余额不足、
328				// 依旧待审批，账本不增长。
329				ledgerBefore := len(w.Ledger())
330				if _, err := approveSharedPayer(w, order.second); !errors.Is(err, ErrInsufficientBalance) {
331					t.Fatalf("retry approve of %s err = %v, want ErrInsufficientBalance", order.second.requestID, err)
332				}
333				if len(w.Ledger()) != ledgerBefore {
334					t.Fatalf("retry approve grew ledger %d -> %d", ledgerBefore, len(w.Ledger()))
335				}
336				checkSharedPayerOutcome(t, w, payerInit, order.first, order.second, createdAt, waitDeadline, approveAt)
337			})
338		}
339	}
340	
341	// payerRaceBias 控制两个批准 goroutine 的起跑方式，使“50 先获批”与“40 先
342	// 获批”两种先后顺序都能在并发 harness 下被确定性地观察到：偏向模式下后一
343	// 个 goroutine 等前一个的 Approve 完全返回后才起跑，先后顺序不依赖调度器
344	// 或睡眠时间。
345	type payerRaceBias int
346	
347	const (
348		payerRaceSimultaneous payerRaceBias = iota
349		payerRace50First
350		payerRace40First
351	)
352	
353	// raceSharedPayerApprovals 用出资账户的同一个有效审批会话从两个 goroutine
354	// 同时批准两笔跨策略的待审批请求，断言恰有一笔成功、另一笔返回
355	// ErrInsufficientBalance，返回胜出与失败的一侧。bias 用于确定性地覆盖两种
356	// 先后顺序。
357	func raceSharedPayerApprovals(t *testing.T, w *Wallet, bias payerRaceBias) (winner, loser payerContestSide) {
358		t.Helper()
359		sides := []payerContestSide{sharePayerSide50, sharePayerSide40}
360		views := make([]RequestView, 2)
361		errs := make([]error, 2)
362		gates := []chan struct{}{make(chan struct{}), make(chan struct{})}
363		done := []chan struct{}{make(chan struct{}), make(chan struct{})}
364	
365		var wg sync.WaitGroup
366		for i, side := range sides {
367			i, side := i, side
368			wg.Add(1)
369			go func() {
370				defer wg.Done()
371				<-gates[i]
372				views[i], errs[i] = approveSharedPayer(w, side)
373				close(done[i])
374			}()
375		}
376		// 偏向模式下先放行指定的一侧，并等它的批准完整结束后再放行另一侧，
377		// 确定性地产生先后顺序；同时模式下两个闸门一起关闭。
378		switch bias {
379		case payerRace50First:
380			close(gates[0])
381			<-done[0]
382			close(gates[1])
383		case payerRace40First:
384			close(gates[1])
385			<-done[1]
386			close(gates[0])
387		default:
388			close(gates[0])
389			close(gates[1])
390		}
391		wg.Wait()
392	
393		successes := 0
394		for i, side := range sides {
395			switch {
396			case errs[i] == nil:
397				successes++
398				winner = side
399				if views[i].State != RequestReserved || views[i].ApproverAccountID != "payer" {
400					t.Fatalf("winning approve view for %s = %+v, want reserved by payer", side.requestID, views[i])
401				}
402			case errors.Is(errs[i], ErrInsufficientBalance):
403				loser = side
404			default:
405				t.Fatalf("approve for %s err = %v, want nil or ErrInsufficientBalance", side.requestID, errs[i])
406			}
407		}
408		if successes != 1 || winner == (payerContestSide{}) || loser == (payerContestSide{}) {
409			t.Fatalf("contested approvals must yield exactly one success and one balance error, got winner %+v loser %+v errs %v",
410				winner, loser, errs)
411		}
412		return winner, loser
413	}
414	
415	// TestSharedPayerConcurrentContestedApprovals 并发复现题述场景：出资账户
416	// 可用 70，用有效审批会话同时批准两条不同策略下的待审批请求（50 与 40）
417	// 时，只能有一笔成功，另一笔返回 ErrInsufficientBalance 并继续待审批——
418	// 两笔请求来自不同策略也不能各自使用同一笔余额。无需指定哪笔先获批：
419	// 50 胜出与 40 胜出两种结果都必须符合同一规则。三种起跑方式各跑多轮，
420	// 并要求两侧都至少胜出一次，确保两种先后顺序都被真正验证。
421	func TestSharedPayerConcurrentContestedApprovals(t *testing.T) {
422		const (
423			payerInit  int64 = 70
424			iterations       = 24
425		)
426		wins := map[string]int{}
427		for _, bias := range []struct {
428			name string
429			mode payerRaceBias
430		}{
431			{"simultaneous", payerRaceSimultaneous},
432			{"fee50-first", payerRace50First},
433			{"fee40-first", payerRace40First},
434		} {
435			for i := 0; i < iterations; i++ {
436				w, c, createdAt, waitDeadline := setupSharedPayerApproveContest(t, payerInit)
437				approveAt := c.t.Add(10 * time.Second)
438				c.t = approveAt
439	
440				winner, loser := raceSharedPayerApprovals(t, w, bias.mode)
441				wins[winner.requestID]++
442				checkSharedPayerOutcome(t, w, payerInit, winner, loser, createdAt, waitDeadline, approveAt)
443			}
444		}
445		if len(wins) != 2 {
446			t.Fatalf("each side must win at least once, got winner distribution %v", wins)
447		}
448		t.Logf("winner distribution: %v", wins)
449	}
450	
451	// TestSharedPayerExactBalanceBothApproved 覆盖边界：出资账户可用余额恰为
452	// 90（两笔费用 50+40 之和），其余条件相同。两次批准都应成功：可用余额
453	// 恰好用尽为 0、预留余额 90，两条策略分别预留 50 和 40。各策略额度充足
454	// 时，不能把不同策略的费用合并成同一条策略的额度占用（任一条策略的
455	// 预留都不超过自己的累计上限 100），也不能因余额恰好用尽而拒绝后完成
456	// 的批准。两种批准顺序都覆盖。
457	func TestSharedPayerExactBalanceBothApproved(t *testing.T) {
458		const payerInit int64 = 90
459		for _, order := range []struct {
460			name   string
461			first  payerContestSide
462			second payerContestSide
463		}{
464			{"fee50-first", sharePayerSide50, sharePayerSide40},
465			{"fee40-first", sharePayerSide40, sharePayerSide50},
466		} {
467			t.Run(order.name, func(t *testing.T) {
468				w, c, createdAt, waitDeadline := setupSharedPayerApproveContest(t, payerInit)
469				approveAt := c.t.Add(10 * time.Second)
470				c.t = approveAt
471	
472				first, err := approveSharedPayer(w, order.first)
473				if err != nil {
474					t.Fatalf("first approve of %s: %v", order.first.requestID, err)
475				}
476				if first.State != RequestReserved {
477					t.Fatalf("first approve state = %v, want reserved", first.State)
478				}
479				// 第一笔预留后可用余额恰好等于第二笔费用：第二笔必须批准成功，
480				// 不能因余额恰好用尽而被拒绝。
481				second, err := approveSharedPayer(w, order.second)
482				if err != nil {
483					t.Fatalf("second approve of %s with exactly enough balance: %v", order.second.requestID, err)
484				}
485				if second.State != RequestReserved {
486					t.Fatalf("second approve state = %v, want reserved", second.State)
487				}
488	
489				// 两笔都已预留：各带出资账户的批准决定，预留时刻即批准时刻，
490				// 提交时间与等待截止时间保持申请时原值。
491				for _, side := range []payerContestSide{order.first, order.second} {
492					req, err := w.Request(side.account, side.requestID)
493					if err != nil {
494						t.Fatal(err)
495					}
496					if req.State != RequestReserved || req.EstimatedFee != side.fee {
497						t.Fatalf("%s view = %+v, want reserved fee %d", side.requestID, req, side.fee)
498					}
499					if req.ApproverAccountID != "payer" || !req.DecidedAt.Equal(approveAt) || !req.ReservedAt.Equal(approveAt) {
500						t.Fatalf("%s decision/reserve timing = %+v, want payer decision at %v", side.requestID, req, approveAt)
501					}
502					if !req.CreatedAt.Equal(createdAt) || !req.WaitDeadline.Equal(waitDeadline) {
503						t.Fatalf("%s timing changed: created %v want %v, deadline %v want %v",
504							side.requestID, req.CreatedAt, createdAt, req.WaitDeadline, waitDeadline)
505					}
506				}
507	
508				// 余额恰好用尽：可用 0、预留 90。
509				if bal, _ := w.Balance("payer"); bal != (Balances{Available: 0, Reserved: 90}) {
510					t.Fatalf("payer balance = %+v, want {0 90}", bal)
511				}
512				// 两条策略分别预留 50 和 40，互不合并占用，已花费都为 0。
513				if pv, _ := w.Policy(sharePayerPolicy50); pv.ReservedTotal != sharePayerFee50 || pv.SpentTotal != 0 {
514					t.Fatalf("policy %s totals = reserved %d spent %d, want 50/0",
515						sharePayerPolicy50, pv.ReservedTotal, pv.SpentTotal)
516				}
517				if pv, _ := w.Policy(sharePayerPolicy40); pv.ReservedTotal != sharePayerFee40 || pv.SpentTotal != 0 {
518					t.Fatalf("policy %s totals = reserved %d spent %d, want 40/0",
519						sharePayerPolicy40, pv.ReservedTotal, pv.SpentTotal)
520				}
521	
522				// 账本：两条待审批留痕 + 两笔全额预留 + 两条零金额批准，共 6 条。
523				all := w.Ledger()
524				if len(all) != 6 {
525					t.Fatalf("ledger entries = %d, want 6 (2 pending + 2 reserve + 2 approval): %+v", len(all), all)
526				}
527				if got := countKind(all, LedgerPendingApproval); got != 2 {
528					t.Fatalf("pending entries = %d, want 2", got)
529				}
530				if got := countKind(all, LedgerReserve); got != 2 {
531					t.Fatalf("reserve entries = %d, want 2", got)
532				}
533				if got := countKind(all, LedgerApproval); got != 2 {
534					t.Fatalf("approval entries = %d, want 2", got)
535				}
536				for _, kind := range []LedgerKind{LedgerRejection, LedgerRefund, LedgerSettle, LedgerExpiration, LedgerCancellation} {
537					if got := countKind(all, kind); got != 0 {
538						t.Fatalf("ledger kind %v entries = %d, want none", kind, got)
539					}
540				}
541				// 请求与账本相互核对：每笔请求都能找到自己的全额预留记录
542				// （出资账户、批准时刻）与零金额批准记录（使用账户、批准时刻）。
543				for _, side := range []payerContestSide{order.first, order.second} {
544					res, ok := ledgerEntryFor(all, LedgerReserve, side.requestID)
545					if !ok {
546						t.Fatalf("missing reserve entry for %s", side.requestID)
547					}
548					if res.AccountID != "payer" || res.Amount != side.fee || !res.At.Equal(approveAt) {
549						t.Fatalf("reserve entry for %s = %+v, want payer %d at approve time", side.requestID, res, side.fee)
550					}
551					app, ok := ledgerEntryFor(all, LedgerApproval, side.requestID)
552					if !ok {
553						t.Fatalf("missing approval entry for %s", side.requestID)
554					}
555					if app.AccountID != side.account || app.Amount != 0 || !app.At.Equal(approveAt) {
556						t.Fatalf("approval entry for %s = %+v, want zero-amount entry for %s at approve time",
557							side.requestID, app, side.account)
558					}
559				}
560				// 出资账户账本的资金求和解释最终余额：可用 = 90 - 50 - 40 = 0，
561				// 预留 = 50 + 40 = 90。
562				var reservedSum int64
563				for _, e := range w.AccountLedger("payer") {
564					if e.Kind != LedgerReserve {
565						t.Fatalf("unexpected payer ledger entry: %+v", e)
566					}
567					reservedSum += e.Amount
568				}
569				if reservedSum != 90 {
570					t.Fatalf("payer reserve sum = %d, want 90", reservedSum)
571				}
572				if bal, _ := w.Balance("payer"); bal.Available != payerInit-reservedSum || bal.Reserved != reservedSum {
573					t.Fatalf("ledger sums do not explain balances: %+v", bal)
574				}
575			})
576		}
577	}
578

